package net.civeira.phylax.features.notification.smtpoutboundconfig.domain;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.crypto.AesCipherService;
import net.civeira.phylax.features.access.tenant.domain.TenantReference;

class SmtpOutboundConfigChangeSetUnitTest {

  /**
   * @autogenerated CachedGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_smtp_outbound_config_change_set_builder() {
    AesCipherService cypher = Mockito.mock(AesCipherService.class);
    SmtpOutboundConfigChangeSet one =
        new SmtpOutboundConfigChangeSet().uid("one").tenant(TenantReference.of("one")).host("one")
            .port(1).login("one").passwordPlain("one").senderName("one").senderEmail("one")
            .timeout(1).useTls(true).maxRetries(1).retryDelay(1).rateLimit(1).version(1).newUid();
    one.uid("two");
    Assertions.assertEquals("two", one.getUid().get(), "Value must equals to the assigned value");
    one.unset("uid");
    Assertions.assertFalse(one.getUid().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(TenantReference.of("one"), one.getTenant().get(),
        "Value must equals to the intial value");
    one.tenant(TenantReference.of("two"));
    Assertions.assertEquals(TenantReference.of("two"), one.getTenant().get(),
        "Value must equals to the assigned value");
    one.unset("tenant");
    Assertions.assertFalse(one.getTenant().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getHost().get(), "Value must equals to the intial value");
    one.host("two");
    Assertions.assertEquals("two", one.getHost().get(), "Value must equals to the assigned value");
    one.unset("host");
    Assertions.assertFalse(one.getHost().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(1, one.getPort().get(), "Value must equals to the intial value");
    one.port(2);
    Assertions.assertEquals(2, one.getPort().get(), "Value must equals to the assigned value");
    one.unset("port");
    Assertions.assertFalse(one.getPort().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getLogin().get(), "Value must equals to the intial value");
    one.login("two");
    Assertions.assertEquals("two", one.getLogin().get(), "Value must equals to the assigned value");
    one.unset("login");
    Assertions.assertFalse(one.getLogin().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getPasswordPlain(cypher).get(),
        "Value must equals to the intial value");
    one.passwordPlain("two");
    Assertions.assertEquals("two", one.getPasswordPlain(cypher).get(),
        "Value must equals to the assigned value");
    one.unset("password");
    Assertions.assertFalse(one.getPasswordPlain(cypher).isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getSenderName().get(),
        "Value must equals to the intial value");
    one.senderName("two");
    Assertions.assertEquals("two", one.getSenderName().get(),
        "Value must equals to the assigned value");
    one.unset("senderName");
    Assertions.assertFalse(one.getSenderName().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getSenderEmail().get(),
        "Value must equals to the intial value");
    one.senderEmail("two");
    Assertions.assertEquals("two", one.getSenderEmail().get(),
        "Value must equals to the assigned value");
    one.unset("senderEmail");
    Assertions.assertFalse(one.getSenderEmail().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(1, one.getTimeout().get(), "Value must equals to the intial value");
    one.timeout(2);
    Assertions.assertEquals(2, one.getTimeout().get(), "Value must equals to the assigned value");
    one.unset("timeout");
    Assertions.assertFalse(one.getTimeout().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(true, one.getUseTls().get(), "Value must equals to the intial value");
    one.useTls(false);
    Assertions.assertEquals(false, one.getUseTls().get(),
        "Value must equals to the assigned value");
    one.unset("useTls");
    Assertions.assertFalse(one.getUseTls().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(1, one.getMaxRetries().get(), "Value must equals to the intial value");
    one.maxRetries(2);
    Assertions.assertEquals(2, one.getMaxRetries().get(),
        "Value must equals to the assigned value");
    one.unset("maxRetries");
    Assertions.assertFalse(one.getMaxRetries().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(1, one.getRetryDelay().get(), "Value must equals to the intial value");
    one.retryDelay(2);
    Assertions.assertEquals(2, one.getRetryDelay().get(),
        "Value must equals to the assigned value");
    one.unset("retryDelay");
    Assertions.assertFalse(one.getRetryDelay().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(1, one.getRateLimit().get(), "Value must equals to the intial value");
    one.rateLimit(2);
    Assertions.assertEquals(2, one.getRateLimit().get(), "Value must equals to the assigned value");
    one.unset("rateLimit");
    Assertions.assertFalse(one.getRateLimit().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(0, one.getVersion().get(), "Value must equals to the intial value");
    one.version(2);
    Assertions.assertEquals(2, one.getVersion().get(), "Value must equals to the assigned value");
    one.unset("version");
    Assertions.assertFalse(one.getVersion().isPresent(),
        "After unset, the valeue must be dissapear");
  }
}
